from typing import Generic, TypeVar, List
T = TypeVar("T")

class Stack(Generic[T]):
    """A small generic stack with push, pop, and peek.

    Examples:
        >>> s: Stack[int] = Stack()
        >>> s.push(1); s.push(2)
        >>> s.peek()
        2
        >>> s.pop()
        2
        >>> s.pop()
        1
    """
    def __init__(self) -> None:
        self._items: List[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self) -> T:
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def __len__(self) -> int:
        return len(self._items)

if __name__ == "__main__":
    st: Stack[str] = Stack()
    st.push("a"); st.push("b"); st.push("c")
    while len(st) > 0:
        print(st.pop())

from typing import Callable, Dict, List, Any

class EventEmitter:
    """A minimal synchronous pub/sub helper.

    Examples:
        >>> e = EventEmitter()
        >>> logs: List[str] = []
        >>> e.on("ping", lambda msg: logs.append(msg))
        >>> e.emit("ping", "hello")
        >>> logs
        ['hello']
    """
    def __init__(self) -> None:
        self._handlers: Dict[str, List[Callable[..., None]]] = {}

    def on(self, event: str, handler: Callable[..., None]) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def off(self, event: str, handler: Callable[..., None]) -> None:
        if event in self._handlers:
            self._handlers[event].remove(handler)

    def emit(self, event: str, *args: Any) -> None:
        for h in list(self._handlers.get(event, [])):
            h(*args)

if __name__ == "__main__":
    bus = EventEmitter()
    bus.on("greet", lambda n: print("hi", n))
    bus.emit("greet", "world")
    bus.emit("greet", "again")

from typing import Tuple

class Interval:
    """A closed integer interval with overlap and merge utilities.

    Examples:
        >>> a = Interval(1, 5); b = Interval(4, 8)
        >>> a.overlaps(b)
        True
        >>> a.merge(b).bounds()
        (1, 8)
    """
    def __init__(self, lo: int, hi: int):
        if lo > hi:
            raise ValueError("lo must be <= hi")
        self.lo = lo
        self.hi = hi

    def bounds(self) -> Tuple[int, int]:
        return (self.lo, self.hi)

    def overlaps(self, other: "Interval") -> bool:
        return self.lo <= other.hi and other.lo <= self.hi

    def merge(self, other: "Interval") -> "Interval":
        if not self.overlaps(other):
            raise ValueError("intervals do not overlap")
        return Interval(min(self.lo, other.lo), max(self.hi, other.hi))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Interval):
            return NotImplemented
        return self.bounds() == other.bounds()

if __name__ == "__main__":
    print(Interval(1, 4).merge(Interval(3, 6)).bounds())

from typing import Dict, Iterable, List
from collections import OrderedDict

class OrderedCounter(Dict[str, int]):
    """Counter that remembers first-seen order of keys.

    Examples:
        >>> c = OrderedCounter(["b", "a", "b", "c", "a"])
        >>> c.keys_ordered()
        ['b', 'a', 'c']
        >>> c["b"]
        2
    """
    def __init__(self, items: Iterable[str] = ()):
        super().__init__()
        self._order: "OrderedDict[str, None]" = OrderedDict()
        for v in items:
            self[v] = self.get(v, 0) + 1

    def __setitem__(self, key: str, value: int) -> None:
        if key not in self._order:
            self._order[key] = None
        super().__setitem__(key, value)

    def keys_ordered(self) -> List[str]:
        return list(self._order.keys())

if __name__ == "__main__":
    oc = OrderedCounter(["x", "y", "x", "z"])
    print(oc.keys_ordered(), dict(oc))

from typing import Callable, TypeVar, Any, Tuple
import time

F = TypeVar("F", bound=Callable[..., Any])

def retry(max_attempts: int = 3, delay: float = 0.0, exceptions: Tuple[type, ...] = (Exception,)):
    """Decorator that retries a function on failure.

    Args:
        max_attempts: Total attempts including the first call.
        delay: Seconds to sleep between attempts.
        exceptions: Tuple of exception types to catch.

    Returns:
        A wrapped function with retry behavior.

    Examples:
        >>> @retry(max_attempts=2, exceptions=(ValueError,))
        ... def boom(): raise ValueError("nope")
        >>> try:
        ...     boom()
        ... except ValueError as e:
        ...     print("gave up:", e.args[0])
        gave up: nope
    """
    def decorator(func: F) -> F:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last: Exception
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == max_attempts:
                        raise
                    if delay > 0:
                        time.sleep(delay)
            raise last
        return wrapper  # type: ignore[return-value]
    return decorator

if __name__ == "__main__":
    calls = {"n": 0}
    @retry(max_attempts=4, delay=0)
    def flaky() -> int:
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("fail")
        return 42
    print(flaky())
